n></>:<><p>{s.companies.filter(c=>actionIds.includes(c.id)).map(c=>c.name).join(', ')}</p><Field label="Reason (required)"><textarea value={reason} onChange={e=>Reason(e.target.value)}/></Field><Button disabled={!reason.trim()} onClick={()=>{if(modal==='reject')reviewed(actionIds,'Rejected',reason);else actionIds.forEach(id=>{const c=s.companies.find(c=>c.id===id)!;update(id,{suppressed:modal==='suppress',contact:modal==='suppress'?'Suppressed':'Not researched',activity:[new Date().toISOString()+' · Suppression changed. '+reason,...c.activity]})});closeModal()}}>{t("Confirm")}</Button></>}</DialogContent></Dialog><Dialog open={!!settingsInfo} onOpenChange={v=>{if(!v)SI('')}}><DialogContent><DialogTitle>{settingsInfo} · {t('Not connected')}</DialogTitle><DialogDescription>{t("Future backend integration requirements")}</DialogDescription><p>{t("A server-side adapter, workspace authorisation, provider agreement, usage limits, audit events and reviewed data policies are required.")}</p><p>{t("No credentials are collected here. The live adapter fails explicitly until implemented.")}</p></DialogContent></Dialog><AlertDialog open={reset} onOpenChange={Reset}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{t('Reset demo data')}?</AlertDialogTitle><AlertDialogDescription>{t("This clears BuyerOS demo keys, session edits and synthetic workflow state. Other browser storage is untouched.")}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{t('Cancel')}</AlertDialogCancel><AlertDialogAction onClick={()=>{localStorage.removeItem('buyeros-demo-v1');localStorage.removeItem('buyeros-prefs-v1');localStorage.removeItem('buyeros-drafts-v1');setS(seed());AR('sample-run');OfferSet({...sample});Sel([]);B(null);DI(null);SL(false);clear();go('/app/discover')}}>{t("Reset demo")}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog><Toaster richColors position="bottom-right"/></SidebarProvider></LocaleContext.Provider>}
