'use client';
import {uid} from '@/lib/id';
import {LiveWorkspace} from './live/workspace-picker';
import {useState,useEffect,useMemo,useRef} from 'react';
import {usePathname,useRouter} from 'next/navigation';
import {LayoutDashboard,Search,FolderOpen,Mail,ChartNoAxesCombined,Settings,Plus,ChevronRight,ArrowUpRight,ArrowLeft,ArrowRight,SlidersHorizontal,Download,Check,Globe2,Building2,ShieldCheck,FileText,ChevronDown,Menu,Wallet,Info,MoreHorizontal,RotateCcw,CheckCheck} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarContent,SidebarHeader,SidebarFooter,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarGroup,SidebarTrigger} from '@/components/ui/sidebar';
import {Sheet,SheetContent,SheetTitle,SheetDescription} from '@/components/ui/sheet';
import {Dialog,DialogContent,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {AlertDialog,AlertDialogContent,AlertDialogHeader,AlertDialogTitle,AlertDialogDescription,AlertDialogFooter,AlertDialogCancel,AlertDialogAction} from '@/components/ui/alert-dialog';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Table,TableHeader,TableHead,TableRow,TableBody,TableCell} from '@/components/ui/table';
import {Checkbox} from '@/components/ui/checkbox';
import {Progress} from '@/components/ui/progress';
import {Pagination,PaginationContent,PaginationItem,PaginationPrevious,PaginationNext} from '@/components/ui/pagination';
import {toast,Toaster} from 'sonner';
import {Button,Pick,Pill,Field} from './ui';
import {BuyerDetail} from './buyers/detail';
import {Wizard,sample,type Offer} from './discovery/wizard';
import {advanceRun,cancelRun,retryRun} from '@/services/run-engine';
import {seed,base} from '@/data/demo/fixtures';
import {usage,block,quote,confirm,csv,download,money} from '@/services/mock-client';
import {zh} from '@/locales';
import {LocaleContext} from '@/locales/context';
import type {Store,Company,Evidence,OutreachDraft,SearchRun} from '@/services/contracts';
import {type DataMode,availabilityFor} from '@/services/live/mode';
import {demoEffectsEnabled,emptyStore,modeBanner} from '@/services/live/workspace-logic';
import {readDemoState,writePrefs} from '@/services/live/storage';
import {LiveOverview} from './live/overview';
import {LiveUnavailable} from './live/unavailable';
import {LiveOfferWizard} from './live/offer-wizard';
import {LiveProfilePanel} from './live/profile';
import {LiveBuyers} from './live/buyers';
const nav=[['Overview','/app',LayoutDashboard],['Find Buyers','/app/discover',Search],['Buyer Lists','/app/lists',FolderOpen],['Outreach','/app/outreach',Mail],['Results','/app/results',ChartNoAxesCombined]] as const;
const stages=['Prepare profile','Generate queries','Discover companies','Remove duplicates','Assess evidence','Results ready'];
export default function Workspace({mode='demo'}:{mode?:DataMode}){const current=usePathname();return current==='/auth/callback'?null:mode==='live'?<LiveWorkspace/>:<DemoWorkspace mode={mode}/>}
function DemoWorkspace({mode='demo'}:{mode?:DataMode}){const [s,setS]=useState<Store>(()=>mode==='demo'?seed():emptyStore()),[loaded,L]=useState(false);const path=usePathname()||'/',router=useRouter();const go=(url:string)=>router.push(url);const t=(x:string)=>s.locale==='zh-HK'?(zh[x]||x):x;
const [sidebarOpen,SidebarOpen]=useState(true);useEffect(()=>{const m=window.matchMedia('(min-width:1024px)');const change=()=>SidebarOpen(m.matches);change();m.addEventListener('change',change);return()=>m.removeEventListener('change',change)},[]);
const stateRef=useRef(s);stateRef.current=s;useEffect(()=>{if(!demoEffectsEnabled(mode))return;const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();Promise.resolve(context.registerTool({name:'list_demo_buyers',title:'List demo buyers',description:'Read fictional buyers and their distinct fit, review and contact states. Never returns real research.',inputSchema:{type:'object',properties:{market:{type:'string',enum:['Germany','Netherlands','Belgium']}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input:unknown){const a=input as {market?:string};if(!a||typeof a!=='object'||Object.keys(a).some(k=>k!=='market')||(a.market&&!['Germany','Netherlands','Belgium'].includes(a.market)))throw new Error('INVALID_INPUT');return stateRef.current.companies.filter(c=>!a.market||c.market===a.market).map(c=>({id:c.id,name:c.name,market:c.market,fit:c.fit,review:c.review,contact:c.contact,dataMode:'demo'}))}},{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[mode]);
const [q,Q]=useState(''),[market,M]=useState('All markets'),[fit,F]=useState('All fit verdicts'),[review,R]=useState('All reviews'),[contact,C]=useState('All contacts'),[type,T]=useState('All buyer types'),[sourceType,ST]=useState('All sources'),[recency,RC]=useState('Any observation date'),[sort,Sort]=useState('Best fit first'),[page,P]=useState(1),[size,Size]=useState('8'),[selected,Sel]=useState<string[]>([]),[filters,Filters]=useState(false),[optional,Optional]=useState(false),[preset,Preset]=useState<any>(null);
const [buyerId,B]=useState<string|null>(null),[source,Source]=useState<Evidence|null>(null),[modal,Modal]=useState(''),[actionIds,Ids]=useState<string[]>([]),[reason,Reason]=useState(''),[listName,LN]=useState(''),[listId,LI]=useState('list-1'),[quoteId,QI]=useState<string|null>(null),[reset,Reset]=useState(false),[offer,OfferSet]=useState<Offer>({...sample}),[activeRun,AR]=useState('sample-run'),[draftId,DI]=useState<string|null>(null),[resultTab,RT]=useState('Outcomes'),[settingsInfo,SI]=useState(''),[savedLocal,SL]=useState(false);
useEffect(()=>{if(!demoEffectsEnabled(mode))return;try{const demo=readDemoState(window.localStorage,mode);const raw=demo['buyeros-demo-v1'];if(typeof raw==='string'){const parsed=JSON.parse(raw);if(Array.isArray(parsed.companies)&&Array.isArray(parsed.runs)&&parsed.companies.length===24)setS(parsed);}const draftsRaw=demo['buyeros-drafts-v1'];if(typeof draftsRaw==='string'){const drafts=JSON.parse(draftsRaw);if(Array.isArray(drafts))setS(x=>({...x,drafts:drafts.filter(d=>d.dataMode==='demo'&&d.recipient?.endsWith('.example')).map(d=>({...d,status:'Draft',approvedRevision:undefined,approvedAt:undefined}))}));}const p=demo['buyeros-prefs-v1'];if(typeof p==='string'){const pref=JSON.parse(p);setS(x=>({...x,locale:pref.locale==='zh-HK'?'zh-HK':'en'}));}}catch{}L(true)},[mode]);
useEffect(()=>{if(!demoEffectsEnabled(mode))return;if(loaded)writePrefs(window.localStorage,mode,{locale:s.locale});document.documentElement.lang=s.locale},[s.locale,loaded,mode]);
useEffect(()=>{P(1);Sel([])},[q,market,fit,review,contact,type,sourceType,recency,size,path]);
useEffect(()=>{const id=path.split('/')[3];if(path.startsWith('/app/discover/')&&id&&id!=='new'&&s.runs.some(r=>r.id===id))AR(id)},[path]);
const run=s.runs.find(r=>r.id===activeRun)||s.runs[0];
useEffect(()=>{if(!demoEffectsEnabled(mode))return;if(run?.status!=='Running')return;const timer=setTimeout(()=>setS(old=>advanceRun(old,run.id)),700);return()=>clearTimeout(timer)},[mode,run?.id,run?.stage,run?.status]);
const u=demoEffectsEnabled(mode)?usage(s):{spent:0,contactSpent:0,reserved:0,remaining:0,accepted:0,valid:0,pending:0},isWizard=path==='/app/discover/new',isBuyers=path==='/app/discover',isLists=path.startsWith('/app/lists'),isOutreach=path.startsWith('/app/outreach'),isResults=path.startsWith('/app/results'),isSettings=path.startsWith('/app/settings'),isOverview=path==='/app',isFull=path.startsWith('/app/buyers/');const listRoute=isLists?path.split('/')[3]:undefined;const currentList=s.lists.find(l=>l.id===(listRoute||listId));const fullBuyer=isFull?s.companies.find(c=>c.id===path.split('/')[3]):undefined;const buyer=s.companies.find(c=>c.id===buyerId);
const rows=useMemo(()=>{if(!demoEffectsEnabled(mode))return [];let r=s.companies;if(!isLists&&run.id!=='sample-run')r=r.slice(0,run.count);if(isLists)r=r.filter(c=>currentList?.members.includes(c.id));return r.filter(c=>(!q||c.name.toLowerCase().includes(q.toLowerCase()))&&(market==='All markets'||c.market===market)&&(type==='All buyer types'||c.type===type)&&(fit==='All fit verdicts'||c.fit===fit)&&(review==='All reviews'||c.review===review)&&(contact==='All contacts'||c.contact===contact)&&(sourceType==='All sources'||c.evidence.some(e=>e.type===sourceType))&&(recency!=='Old sample evidence')).sort((a,b)=>sort==='Name A–Z'?a.name.localeCompare(b.name):['Match','Needs review','Not a match'].indexOf(a.fit)-['Match','Needs review','Not a match'].indexOf(b.fit))},[mode,s.companies,q,market,type,fit,review,contact,sourceType,recency,sort,isLists,currentList,run]);const pageCount=Math.max(1,Math.ceil(rows.length/+size)),pageRows=rows.slice((Math.min(page,pageCount)-1)*+size,Math.min(page,pageCount)*+size);const selectedRows=s.companies.filter(c=>selected.includes(c.id));
function update(id:string,patch:Partial<Company>){setS(x=>({...x,companies:x.companies.map(c=>c.id===id?{...c,...patch}:c),drafts:x.drafts.map(d=>d.buyerId===id&&('review'in patch||'suppressed'in patch||'policy'in patch)?{...d,status:'Draft',approvedRevision:undefined,revision:d.revision+1}:d)}))}
function reviewed(ids:string[],status:'Accepted'|'Rejected',why:string){setS(x=>({...x,companies:x.companies.map(c=>ids.includes(c.id)?{...c,review:status,activity:[`${new Date().toISOString()} · Willy Lai: ${c.review} → ${status}. ${why}`,...c.activity]}:c),drafts:x.drafts.map(d=>ids.includes(d.buyerId)?{...d,status:'Draft',approvedRevision:undefined,revision:d.revision+1}:d)}));toast.success(t(status));}
function action(name:string,ids:string[]){Ids(ids);if(name==='accept'){reviewed(ids,'Accepted','Evidence reviewed in demo.');return}if(name==='draft'){const c=s.companies.find(c=>c.id===ids[0])!;if(c.suppressed||c.review!=='Accepted'){toast.error('Accept an unsuppressed buyer before drafting.');return}let d=s.drafts.find(d=>d.buyerId===c.id);if(!d){d={...base,id:uid(),buyerId:c.id,recipient:'purchasing@'+c.name.split(' ')[0].toLowerCase()+'.example',subject:'',body:'',revision:1,status:'Draft',policyReviewed:false,sender:'',delivery:'Not connected',followup:'',objective:'Explore distribution partnership',tone:'Professional',language:'English',valueProposition:sample.value};setS(x=>({...x,drafts:[...x.drafts,d!]}))}DI(d.id);B(null);go('/app/outreach');return}if(name==='lookup'){const qt=quote(s,ids);if(!qt.companyIds.length){QI(null);Modal('lookup');return}if(qt.cost>u.remaining){QI(null);Modal('lookup');return}QI(qt.id);setS(x=>({...x,quotes:[...x.quotes,qt]}));}Modal(name)}
function closeModal(){if(quoteId)setS(x=>({...x,quotes:x.quotes.map(q=>q.id===quoteId&&q.status==='Reserved'?{...q,status:'Cancelled'}:q)}));QI(null);Modal('');Reason('')}
function clear(){Q('');M('All markets');T('All buyer types');F('All fit verdicts');R('All reviews');C('All contacts');ST('All sources');RC('Any observation date')}
function startRun(){const sampleInput=offer.company===sample.company&&offer.product===sample.product&&offer.value===sample.value&&offer.markets===sample.markets&&offer.must===sample.must&&offer.nice===sample.nice&&offer.exclude===sample.exclude&&(offer.buyerTypes||[]).join('|')===sample.buyerTypes?.join('|')&&Object.values(offer.advanced||{}).every(v=>!v.trim())&&!offer.roles?.trim();const id=uid();const r:SearchRun={...base,id,status:sampleInput?'Running':'Limited demonstration',stage:0,count:0,rawCount:0,scenario:offer.scenario,budget:offer.scenario==='Exhausted budget'?0:+offer.budget,startedAt:new Date().toISOString(),profileVersion:s.runs.length+1,target:Math.min(24,+offer.target)};setS(x=>({...x,runs:[r,...x.runs],budget:+offer.contacts,discoveryBudget:+offer.budget}));AR(id);clear();go('/app/discover/'+id)}
const currentQuote=s.quotes.find(x=>x.id===quoteId),eligible=s.companies.filter(c=>actionIds.includes(c.id)&&!block(c));
const draft=s.drafts.find(d=>d.id===draftId)||s.drafts[0],dc=s.companies.find(c=>c.id===draft?.buyerId);function editDraft(patch:Partial<OutreachDraft>){if(!draft)return;setS(x=>({...x,drafts:x.drafts.map(d=>d.id===draft.id?{...d,...patch,revision:d.revision+1,status:'Draft',approvedRevision:undefined,approvedAt:undefined}:d)}))}
const navTitle=isWizard?'New buyer search':isOverview?'Overview':isLists?'Buyer Lists':isOutreach?'Outreach':isResults?'Results':isSettings?'Settings':isFull?'Buyer profile':'Find Buyers';
const filterFields=<><Pick value={market} onChange={M} items={['All markets','Germany','Netherlands','Belgium']} label={t('All markets')}/><Pick value={type} onChange={T} items={['All buyer types','Distributor','System integrator']} label={t('Buyer type')}/><Pick value={fit} onChange={F} items={['All fit verdicts','Match','Needs review','Not a match']}/><Pick value={review} onChange={R} items={['All reviews','Awaiting review','Accepted','Rejected']}/><Pick value={contact} onChange={C} items={['All contacts','Not researched','Provider-marked valid','Catch-all','Unavailable','Suppressed']}/></>;
function buyerTable(){return <><div className="panel results-panel"><div className="table-toolbar"><div className="inline"><h3>{isLists?t(currentList?.name||'Buyer Lists'):t('Buyer results')}</h3><Pill>{rows.length}</Pill></div><div className="inline"><Button variant="ghost" onClick={()=>{const snap={market,type,fit,review,contact,sourceType,recency};Preset(snap);toast.success('Filter preset saved for this session.')}}><FolderOpen size={15}/>{t('Save filter preset')}</Button><Button variant="outline" onClick={()=>download('DEMO_buyers.csv',csv(selected.length?selectedRows:rows),'text/csv;charset=utf-8')}><Download size={15}/>{t('Export sample CSV')}</Button></div></div><div className="filterbar"><div className="searchbox"><Search size={17}/><input aria-label={t('Search companies…')} placeholder={t('Search companies…')} value={q} onChange={e=>Q(e.target.value)}/></div><div className="desktop-filters">{filterFields}</div><Button variant="outline" onClick={()=>Filters(true)}><SlidersHorizontal size={16}/>{t('Filters')}</Button></div><div className="table-sub"><span>{rows.length} {t('companies')} · {selected.length} {t('selected')}</span><div className="inline">{preset&&<Button variant="ghost" onClick={()=>{M(preset.market);T(preset.type);F(preset.fit);R(preset.review);C(preset.contact);ST(preset.sourceType);RC(preset.recency)}}>{t('Apply saved preset')}</Button>}<Pick value={sort} onChange={Sort} items={['Best fit first','Name A–Z']}/></div></div>{selected.length>0&&<div className="bulkbar"><b>{selected.length} {t("selected")}</b><button onClick={()=>Sel(rows.map(c=>c.id))}>{t("Select all")}{rows.length} {t("filtered companies")}</button>{['accept','reject','save','lookup'].map(a=><Button size="sm" variant="outline" key={a} onClick={()=>action(a,selected)}>{t({accept:'Accept buyer',reject:'Reject buyer',save:'Save to list',lookup:'Find business contacts'}[a]!)}</Button>)}{isLists&&<Button size="sm" variant="outline" onClick={()=>{setS(x=>({...x,lists:x.lists.map(l=>l.id===currentList?.id?{...l,members:l.members.filter(id=>!selected.includes(id))}:l)}));Sel([])}}>{t('Remove from list')}</Button>}<button onClick={()=>Sel([])}>{t("Clear")}</button></div>}<div className="desktop-table"><Table><TableHeader><TableRow><TableHead><Checkbox aria-label="Select current page" checked={pageRows.length>0&&pageRows.every(c=>selected.includes(c.id))} onCheckedChange={v=>Sel(v?Array.from(new Set([...selected,...pageRows.map(c=>c.id)])):selected.filter(id=>!pageRows.some(c=>c.id===id)))}/></TableHead><TableHead>{t('Company')}</TableHead><TableHead>{t('Buyer type')}</TableHead><TableHead className="fit-column">{t('Why it fits')}</TableHead><TableHead>{t('Contact status')}</TableHead><TableHead>{t('Review status')}</TableHead>{optional&&<TableHead>{t("Owner")}</TableHead>}<TableHead><span className="sr-only">{t("Open buyer")}</span></TableHead></TableRow></TableHeader><TableBody>{pageRows.map(c=><TableRow key={c.id} data-state={selected.includes(c.id)?'selected':undefined}><TableCell><Checkbox aria-label={'Select '+c.name} checked={selected.includes(c.id)} onCheckedChange={v=>Sel(v?[...selected,c.id]:selected.filter(id=>id!==c.id))}/></TableCell><TableCell><button className="company-cell" onClick={()=>B(c.id)}><span className={'avatar a'+Number(c.id.split('-')[1])%4}>{c.name.slice(0,2).toUpperCase()}</span><span><b>{c.name}</b><small>{t(c.market)} <span className="dot">·</span> {c.name.split(' ')[0].toLowerCase()}.example</small></span></button></TableCell><TableCell><span className="type-text">{t(c.type)}</span></TableCell><TableCell><button className="why-cell" onClick={()=>B(c.id)}><div className="inline"><Pill kind={c.fit==='Match'?'green':c.fit==='Needs review'?'amber':'gray'}>{c.fit==='Match'&&<Check size={12}/>} {t(c.fit)}</Pill><span className="evidence-count"><FileText size={12}/>{c.evidence.length} {t("sources")}</span></div><p>{t(c.why)}</p></button></TableCell><TableCell><span className={'contact-label '+(c.contact==='Provider-marked val